import {
  VStack,
  Button,
  FormControl,
  FormLabel,
  FormHelperText,
  Input,
} from "@chakra-ui/react";

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { login } from "../endpoints/api";
import { useAuth } from "../contexts/useAuth";

const Register = () => {
  const [username, setUsername] = useState("");
  const [firstName, setFirstName] = useState("");
  const [surname, setSurname] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [password, setPassword] = useState("");
  const [passwordConfirm, setPasswordConfirm] = useState("");
  const navigation = useNavigate();
  const { register } = useAuth();

  const handleRegister = async () => {
    // const success = await login(username, password);
    // if (success) {
    //   await refreshAuth();
    //   navigation("/");
    // }
  };

  return (
    <VStack>
      <FormControl>
        <FormLabel>Username</FormLabel>
        <Input
          onChange={(e) => setUsername(e.target.value)}
          value={username}
          type="text"
        />
        <FormHelperText>Enter your username</FormHelperText>
      </FormControl>

      <FormControl>
        <FormLabel>First name</FormLabel>
        <Input
          onChange={(e) => setFirstName(e.target.value)}
          value={firstName}
          type="text"
        />
        <FormHelperText>Enter your first name</FormHelperText>
      </FormControl>

      <FormControl>
        <FormLabel>Surname</FormLabel>
        <Input
          onChange={(e) => setSurname(e.target.value)}
          value={surname}
          type="text"
        />
        <FormHelperText>Enter your surname</FormHelperText>
      </FormControl>

      <FormControl>
        <FormLabel>Last name</FormLabel>
        <Input
          onChange={(e) => setLastName(e.target.value)}
          value={lastName}
          type="text"
        />
        <FormHelperText>Enter your last name</FormHelperText>
      </FormControl>

      <FormControl>
        <FormLabel>Email</FormLabel>
        <Input
          onChange={(e) => setEmail(e.target.value)}
          value={email}
          type="text"
        />
        <FormHelperText>Enter your email</FormHelperText>
      </FormControl>

      <FormControl>
        <FormLabel>Role</FormLabel>
        <Input
          onChange={(e) => setRole(e.target.value)}
          value={role}
          type="text"
        />
        <FormHelperText>Enter your role</FormHelperText>
      </FormControl>

      <FormControl>
        <FormLabel>Password</FormLabel>
        <Input
          onChange={(e) => setPassword(e.target.value)}
          value={password}
          type="password"
        />
        <FormHelperText>Enter your password</FormHelperText>
      </FormControl>
      <FormControl>
        <FormLabel>Password Confirm</FormLabel>
        <Input
          onChange={(e) => setPasswordConfirm(e.target.value)}
          value={passwordConfirm}
          type="password"
        />
        <FormHelperText>Confirm password</FormHelperText>
      </FormControl>
      <Button onClick={handleRegister}>Register</Button>
    </VStack>
  );
};

export default Register;
